struct RingBuffer {
    int capacity_;
    int head_;
    int tail_;
    int count_;
    int data_[1024];

    RingBuffer(int capacity) : capacity_(capacity), head_(0), tail_(0), count_(0) {}

    bool push(int value) {
        if (count_ >= capacity_) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity_;
        count_++;
        return true;
    }

    bool pop(int& out) {
        if (count_ == 0) return false;
        out = data_[head_];
        head_ = (head_ + 1) % capacity_;
        count_--;
        return true;
    }

    int size() const { return count_; }

    bool empty() const { return count_ == 0; }

    bool full() const { return count_ >= capacity_; }
};

