module sync_fifo #(parameter WIDTH = 8, parameter DEPTH = 4)
  (input clk, input rst_n,
   input wr_en, input [WIDTH-1:0] din,
   input rd_en, output reg [WIDTH-1:0] dout,
   output full, output empty);

  localparam LOG_DEPTH = $clog2(DEPTH);
  reg [LOG_DEPTH-1:0] write_ptr, read_ptr;
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  assign full = (write_ptr == read_ptr) && (wr_en == 1'b1);
  assign empty = (write_ptr == read_ptr) && (rd_en == 1'b0);
  assign dout = mem[read_ptr];

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      write_ptr <= 0;
      read_ptr <= 0;
      mem <= 0;
    end else begin
      if (wr_en && !full) begin
        mem[write_ptr] <= din;
        write_ptr <= write_ptr + 1;
      end
      if (rd_en && !empty) begin
        read_ptr <= read_ptr + 1;
      end
    end
  end

endmodule

