double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    const double* W1 = params;
    const double* b1 = params + n_hidden * n_in;
    const double* W2 = b1 + n_hidden;
    const double* b2 = W2 + n_hidden;

    double total_loss = 0.0;
    double* dL_dz = new double[n_samples];
    double* dL_dh = new double[n_samples * n_hidden];
    double* dL_dz2 = new double[n_samples]; // For W2/b2 gradients

    // Initialize gradients to zero
    for (int i = 0; i < n_samples * n_hidden; ++i) dL_dh[i] = 0.0;
    for (int i = 0; i < n_samples; ++i) dL_dz2[i] = 0.0;

    for (int i = 0; i < n_samples; ++i) {
        const double* x = X + i * n_in;
        const double target = y[i];

        // Forward pass: Hidden layer
        double* h = new double[n_hidden];
        double* z_pre = new double[n_hidden]; // sum W2*h + b2 before activation

        for (int j = 0; j < n_hidden; ++j) {
            double sum = b1[j];
            for (int k = 0; k < n_in; ++k) {
                sum += W1[j * n_in + k] * x[k];
            }
            h[j] = tanh(sum);
            z_pre[j] = W2[j] * h[j];
        }

        double z = z_pre[0]; // Wait, W2 is size n_hidden? 
        // Re-reading spec: "z = sum_j W2[j] * h_j + b2". 
        // But W2 is declared as "n_hidden doubles" in params layout description?
        // Let's re-read carefully:
        // "W2 n_hidden doubles"
        // "z = sum_j W2[j] * h_j + b2"
        // This implies z is a scalar. So W2 must be size n_hidden.
        // But then sum_j W2[j]*h_j is a scalar. Correct.
        // However, in my code above I treated z_pre as array. 
        // Let's fix: z is scalar.

        double z_val = 0.0;
        for (int j = 0; j < n_hidden; ++j) {
            z_val += W2[j] * h[j];
        }
        z_val += b2[0];

        double p = 1.0 / (1.0 + exp(-z_val));

        // Loss for this sample
        double loss_i = -(target * log(p) + (1.0 - target) * log(1.0 - p));
        total_loss += loss_i;

        // Backward pass
        // dL/dz = p - y
        double dz = p - target;
        dL_dz2[i] = dz;

        // dL/dh_j = dL/dz * d(z)/dh_j = dz * W2[j]
        for (int j = 0; j < n_hidden; ++j) {
            dL_dh[i * n_hidden + j] = dz * W2[j];
